#include <omp.h>
#include <vector>
#include <cstddef>
#include <limits>
#include <stdexcept>

int edgeCount(std::vector<int> const& A, size_t N) {
    if (N != 0 && N > std::numeric_limits<size_t>::max() / N) {
        throw std::invalid_argument("edgeCount: N*N overflows size_t");
    }

    const size_t expectedSize = N * N;
    if (A.size() != expectedSize) {
        throw std::invalid_argument("edgeCount: A.size() must be exactly N*N");
    }

    size_t count = 0;

    #pragma omp parallel for reduction(+:count) schedule(static)
    for (size_t idx = 0; idx < expectedSize; ++idx) {
        count += (A[idx] != 0) ? 1u : 0u;
    }

    if (count > static_cast<size_t>(std::numeric_limits<int>::max())) {
        throw std::overflow_error("edgeCount: result does not fit in int");
    }

    return static_cast<int>(count);
}
